mapper.select:
SELECT *
FROM folder
WHERE member_memberId = #{memberId}
AND folderId = #{folderId}

mapper.update:
UPDATE folder
SET name = #{name},
    tag = #{tag}
WHERE folderId = #{folderId}
AND member_memberId = #{member_memberId}

mapper.delete:
DELETE FROM folder
WHERE folderId = #{folderId}
AND member_memberId = #{memberId}
